Ah, you come seeking tests. But do you understand *why* each test must exist? Cause and effect, my friend. Every assertion traces back to a user need, a failure mode, a reason for being.

```typescript
// Checkout.test.tsx
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// The causality begins here - mock the dependencies
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 79.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // HAPPY PATH - The causality chain you hope for
  it('completes full checkout flow successfully', async () => {
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Main St');
    await user.type(screen.getByLabelText(/city/i), 'Springfield');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'John Doe');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/\$79\.98/)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    expect(await screen.findByText(/ORD-12345/)).toBeInTheDocument();
    expect(onComplete).toHaveBeenCalledWith('ORD-12345');
  });

  // VALIDATION - The why of rejection
  describe('form validation', () => {
    it('displays error for invalid ZIP format', async () => {
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates card number is 16 digits', async () => {
      render(<Checkout />);
      // Navigate to payment...
      await user.type(screen.getByLabelText(/card number/i), '411111');
      await user.click(screen.getByRole('button', { name: /review/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/16-digit/i);
    });
  });

  // EDGE CASES - Where causality breaks
  it('shows empty cart message when no items', async () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('handles payment failure with recovery option', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    render(<Checkout />);
    // Navigate through flow...

    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    expect(screen.getByRole('button', { name: /place order/i })).not.toBeDisabled();
  });

  // ACCESSIBILITY - The why of inclusion
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
